from pathlib import Path
import json

path = Path('index.html')
text = path.read_text(encoding='utf-8')

titles = [
    'Right to Invent for Workers Act',
    'Taxpayer Non-Subsidization of Pornography Act',
    'Commercial Oligarchy Antitrust Clause',
    'Common Ownership Competition Act',
    'Constitutional Accountability and Public Standing Amendment',
]
for title in titles:
    if title in text:
        raise SystemExit(f'Policy already present: {title}')

old_version_count = text.count('98.7')
if old_version_count < 5:
    raise SystemExit(f'Expected at least 5 version references to 98.7; found {old_version_count}')
text = text.replace('98.7', '98.8')

def policy(title, sub, body, tags):
    return ('      {title:' + json.dumps(title, ensure_ascii=False) +
            ',sub:' + json.dumps(sub, ensure_ascii=False) +
            ',body:' + json.dumps(body, ensure_ascii=False) +
            ',tags:' + json.dumps(tags, ensure_ascii=False, separators=(',', ':')) +
            ',isNew:true},\n')

def insert_into_section(source, section_id, next_section_id, items):
    start = source.index(f'id:"{section_id}"')
    end = source.index(f'id:"{next_section_id}"', start)
    close = source.rfind('    ]\n  },', start, end)
    if close == -1:
        raise SystemExit(f'Could not locate policy-array close for {section_id}')
    return source[:close] + ''.join(items) + source[close:]

p1 = """<strong>Principle:</strong> A worker's employment shall not give an employer a general ownership claim over that worker's independent creativity, inventions, discoveries, software, designs, writings, patents, trade secrets, or other intellectual property.<br><br>No employer may require, as a condition of employment or continued employment, any contractual provision that assigns to the employer ownership of intellectual property independently created by a worker.<br><br>An employer may claim ownership of an employee-created invention or intellectual property only to the extent the employer proves that the invention or intellectual property was materially developed through one or more of the following:<ul><li>Work performed during compensated company time specifically devoted to the development of that invention or intellectual property.</li><li>Material use of company-owned equipment, laboratories, facilities, supplies, computing resources, funds, or other resources.</li><li>Material use or incorporation of the employer's pre-existing intellectual property, confidential information, or legally protected trade secrets.</li><li>Work specifically commissioned by the employer as part of the employee's assigned duties.</li></ul><br><strong>The burden of proof shall rest entirely upon the employer.</strong> An employee shall not be required to prove that an invention was created independently. Where ownership is disputed, the employer must establish its ownership claim by clear and convincing evidence.<br><br>Incidental or de minimis use of ordinary workplace resources shall not, by itself, transfer ownership. Examples include briefly using ordinary internet access, sending an email, using generally available office equipment, or conceiving an idea while physically present at the workplace.<br><br>Any employment agreement purporting to grant the employer broader ownership rights shall be unenforceable to that extent.<br><br>Employers may require reasonable confidential disclosure of potentially work-related inventions solely for determining ownership, provided that:<ul><li>Disclosure does not itself transfer ownership.</li><li>Disclosed independent inventions remain confidential.</li><li>The employer may not commercially exploit the disclosure without permission.</li><li>Retaliation against employees asserting independent ownership is prohibited.</li></ul><br>Workers whose rights are violated shall be entitled to injunctive relief, recovery of the intellectual property, actual damages, reasonable attorney's fees, and additional statutory damages for knowing violations."""

p3 = """<strong>Principle:</strong> Antitrust law shall protect the public not only against monopoly, but against concentrated groups of dominant corporations that collectively exercise monopoly-like power.<br><br>Federal antitrust law shall expressly recognize <strong>Commercial Oligarchy</strong> as a form of unlawful market domination when a small number of firms collectively possess substantial control over a relevant market and coordinate their conduct to suppress meaningful competition.<br><br>A rebuttable presumption of Commercial Oligarchy shall arise when:<ol><li>Four or fewer independent corporate groups collectively control at least 60% of a relevant national or regional market; and</li><li>Those firms are found to have engaged in explicit collusion, coordinated market allocation, price fixing, output restriction, wage suppression, coordinated exclusion of competitors, coordinated refusal to deal, bid manipulation, or another agreement substantially reducing competition.</li></ol><br>The government shall not be required to establish that any single participant individually constitutes a monopoly.<br><br>Where Commercial Oligarchy is established, courts shall be expressly authorized to impose structural remedies, including:<ul><li>Corporate breakup.</li><li>Divestiture of business units or assets.</li><li>Separation of vertically integrated operations.</li><li>Termination of exclusionary agreements.</li><li>Mandatory divestment of strategically acquired competitors.</li><li>Restrictions on reacquisition.</li><li>Other measures necessary to restore a genuinely competitive market.</li></ul><br>Repeated or prolonged collusion among oligopolistic firms shall create a rebuttable presumption in favor of structural relief rather than fines alone.<br><br>Corporate penalties shall not be treated merely as a cost of doing business. Courts shall consider whether monetary penalties are sufficient to restore competition and, where they are not, shall order structural remedies.<br><br>Executives who knowingly direct criminal price fixing, market allocation, bid rigging, wage-fixing, coordinated suppression of competitors, or similar conduct shall remain individually subject to applicable civil and criminal penalties.<br><br>For purposes of enforcement, antitrust agencies shall evaluate not only the conduct of individual firms, but also whether the structure of the market itself enables a small group of firms to coordinate conduct, suppress competition, or exercise collective economic power comparable to monopoly control."""

text = insert_into_section(text, 'sec-1', 'sec-10', [
    policy('Right to Invent for Workers Act', 'Independent invention belongs to the worker unless the employer proves a material company nexus.', p1, ['economy','liberty','technology','reform']),
    policy('Commercial Oligarchy Antitrust Clause', 'Four dominant firms acting as one can be broken apart like a monopoly.', p3, ['economy','reform','governance']),
])

p2 = """<strong>Principle:</strong> Taxpayers shall not be compelled to financially subsidize the commercial pornography industry.<br><br>No federal department, agency, instrumentality, federally chartered entity, or recipient administering federal funds may knowingly provide public financial assistance for the production, distribution, commercialization, expansion, or operation of commercial pornographic content.<br><br>Prohibited assistance shall include:<ul><li>Direct grants.</li><li>Subsidies.</li><li>Government-backed loans or loan guarantees.</li><li>Industry-specific tax credits or rebates.</li><li>Economic-development incentives.</li><li>Public investment funds.</li><li>Production incentives.</li><li>Bailouts.</li><li>Government equity investments.</li><li>Preferential financing.</li><li>Government procurement of pornographic material except where required for legitimate law-enforcement, judicial, evidentiary, or investigative purposes.</li><li>Grants or intermediary funding knowingly structured to circumvent the prohibition.</li></ul><br>For purposes of this policy, <strong>commercial pornography</strong> means sexually explicit visual or audiovisual material produced and commercially distributed primarily for sexual arousal.<br><br>The prohibition shall not classify medical materials, educational materials, scientific materials, classical or fine art, legitimate journalism, historical records, or ordinary entertainment containing sexual themes as pornography merely because they contain nudity or sexual subject matter.<br><br>No entity may evade the prohibition by routing funding through a subsidiary, nonprofit organization, contractor, affiliated company, or other intermediary.<br><br>Federal agencies shall be required to conduct reasonable due diligence before awarding industry-specific assistance where commercial pornography constitutes a substantial portion of the recipient's business.<br><br>This policy concerns <strong>government financial support</strong>, not ordinary public services available generally under law such as courts, police protection, fire protection, roads, emergency services, or other generally available civic infrastructure."""

p5 = """<strong>Principle:</strong> Constitutional limitations imposed upon public officers and institutions protect the integrity of the Republic itself. Their enforcement shall not depend upon whether one individual can prove a unique private injury.<br><br><strong>Section 1 — Structural Constitutional Injury.</strong><br>A violation of a constitutional limitation imposed upon an officer, branch, agency, or government of the United States constitutes a judicially cognizable constitutional injury where the violation concerns the integrity, allocation, limitation, or lawful exercise of public power, notwithstanding that such injury is suffered by the People generally and produces no individualized injury to the claimant.<br><br><strong>Section 2 — Constitutional Public Cause of Action.</strong><br>Congress shall provide by law a cause of action by which citizens of the United States may seek declaratory or injunctive relief against a specific existing or demonstrably imminent governmental action alleged to constitute such a violation.<br><br>No court shall dismiss such an action for lack of standing on the ground that the claimant lacks:<ul><li>Injury in fact.</li><li>Particularized injury.</li><li>Individualized injury.</li><li>Economic loss.</li><li>Physical injury.</li><li>Property loss.</li><li>Reputational injury.</li><li>An injury distinct from that suffered by the public generally.</li></ul><br><strong>Section 3 — Scope of Review.</strong><br>A Constitutional Public Action may challenge a specific existing or demonstrably imminent:<ul><li>Act of Congress.</li><li>Executive order or executive action.</li><li>Regulation.</li><li>Government expenditure.</li><li>Government program.</li><li>Official policy.</li><li>Exercise of statutory authority.</li><li>Use of public office.</li><li>Receipt of benefits or compensation by a public officer where alleged to violate a constitutional limitation.</li><li>Action or omission of an officer, branch, agency, or government alleged to violate a specific provision of this Constitution.</li></ul>The claimant must identify the constitutional provision allegedly violated and the governmental conduct alleged to violate it.<br><br><strong>Section 4 — Structural and Anti-Corruption Violations.</strong><br>For purposes of this Article, structural constitutional injury includes alleged violations concerning:<ul><li>The separation of powers.</li><li>The allocation of powers between branches.</li><li>Constitutional limits on public office.</li><li>Constitutional restrictions on compensation, emoluments, benefits, or financial conflicts.</li><li>Unconstitutional uses of appropriated funds.</li><li>Unconstitutional delegations or exercises of governmental authority.</li><li>Constitutional limits imposed upon elected or appointed officers.</li><li>Other provisions whose primary purpose is to preserve the lawful structure, integrity, or accountability of government.</li></ul>The fact that an alleged violation harms the public collectively rather than one person uniquely shall not render the claim nonjusticiable.<br><br><strong>Section 5 — Relief.</strong><br>A prevailing claimant may obtain:<ul><li>Declaratory relief.</li><li>Prospective injunctive relief.</li><li>An order restraining continued unconstitutional governmental conduct.</li><li>An order requiring cessation of an unconstitutional program, expenditure, policy, or official act.</li><li>Reasonable attorney's fees where provided by law.</li></ul>Personal monetary damages shall not be awarded solely by virtue of structural constitutional injury unless the claimant independently establishes an individualized injury sufficient to support such damages.<br><br><strong>Section 6 — Preservation of Genuine Cases and Controversies.</strong><br>Nothing in this Article shall require a court to:<ul><li>Issue an advisory opinion concerning hypothetical governmental conduct.</li><li>Adjudicate a claim that is frivolous, collusive, or wholly speculative.</li><li>Adjudicate conduct that is neither existing nor demonstrably imminent.</li><li>Award personal damages without a legally cognizable individual injury.</li><li>Adjudicate a controversy that has ceased to exist and for which no effective relief remains available.</li></ul>The absence of individualized injury, however, shall not by itself render an otherwise concrete constitutional challenge advisory, generalized, or nonjusticiable.<br><br><strong>Section 7 — No Procedural Evasion.</strong><br>Neither Congress, the Executive, nor any agency or officer of the United States may insulate allegedly unconstitutional governmental conduct from judicial review solely by asserting:<ul><li>Lack of individualized standing.</li><li>Generalized grievance.</li><li>Absence of economic or property injury.</li><li>The fact that the alleged constitutional injury is shared by the public.</li><li>Sovereign immunity where the claimant seeks prospective declaratory or injunctive relief against unconstitutional governmental conduct, except as expressly limited by this Constitution.</li></ul>Congress shall provide an express cause of action sufficient to permit such review.<br><br><strong>Section 8 — Enforcement.</strong><br>Congress shall have power to enforce and implement this Article by appropriate legislation, including by establishing causes of action, jurisdiction, procedures, filing requirements, evidentiary standards, and remedies consistent with this Article.<br><br>The several States may likewise provide causes of action and procedures for constitutional judicial review within their respective courts consistent with this Article.<br><br><strong>Section 9 — Constitutional Effect.</strong><br>This Article shall operate as an express qualification upon the standing requirements otherwise arising under Article III with respect to constitutional actions authorized under this Article.<br><br>No interpretation of Article III shall require individualized injury as a condition of standing where this Article expressly provides otherwise."""

text = insert_into_section(text, 'sec-13', 'sec-14', [
    policy('Taxpayer Non-Subsidization of Pornography Act', 'Legal commerce does not create an entitlement to taxpayer subsidy.', p2, ['governance','reform']),
    policy('Constitutional Accountability and Public Standing Amendment', 'Structural constitutional injury gives the People a courthouse door even when no citizen suffers a unique private injury.', p5, ['governance','liberty','reform']),
])

p4 = """<strong>Principle:</strong> No private financial institution should possess economy-wide corporate governance power merely because it serves as the intermediary through which millions of Americans invest their savings.<br><br>Federal antitrust law shall recognize excessive <strong>common ownership, proxy-voting concentration, and asset-management concentration</strong> as potential forms of systemic market power.<br><br>Large asset managers, index-fund managers, institutional investment firms, and affiliated financial groups shall be subject to enhanced competition rules when their holdings or voting authority span competing corporations throughout the same industries.<br><br><strong>1. Common-Ownership Competition Rule.</strong><br>A covered financial institution shall not exercise concentrated voting control over multiple dominant competitors within the same relevant market where that voting power creates a substantial risk of reducing competition.<br><br>Ownership held solely on behalf of clients shall not automatically be treated as the asset manager's beneficial economic property. However, <strong>voting authority, governance influence, board influence, engagement authority, and coordinated control shall be evaluated separately from economic ownership.</strong><br><br><strong>2. Cross-Competitor Voting Limits.</strong><br>Where an asset manager owns substantial positions in two or more major competitors within the same concentrated market, federal regulators may require:<ul><li>Pass-through voting by the underlying investors.</li><li>Proportional or neutral voting.</li><li>Abstention by the asset manager.</li><li>Separation of proxy-voting functions.</li><li>Structural separation of governance functions.</li><li>Divestiture where lesser remedies cannot adequately protect competition.</li></ul>No intermediary shall be permitted to convert passive custody of Americans' investments into unrestricted economy-wide corporate governance power.<br><br><strong>3. Investor Pass-Through Voting.</strong><br>For qualifying index funds, retirement funds, pension-linked investment products, and passive investment products, underlying investors shall increasingly receive the right to direct how the voting power associated with their beneficial holdings is exercised.<br><br>Technology-enabled pass-through voting shall be developed as the preferred long-term model where practicable.<br><br><strong>4. Concentration Review of Asset Managers.</strong><br>Mergers and acquisitions among systemically significant asset managers shall receive enhanced antitrust review based not merely on traditional product-market concentration but upon:<ul><li>Total assets under management.</li><li>Voting power across public corporations.</li><li>Common ownership across competitors.</li><li>Index-fund concentration.</li><li>Proxy-voting concentration.</li><li>Control of retirement savings.</li><li>Control of financial infrastructure.</li><li>Ownership or control of private-market assets.</li><li>Aggregate corporate-governance influence.</li></ul><strong>5. Common Ownership Incorporated Into Antitrust Analysis.</strong><br>The Department of Justice and Federal Trade Commission shall be directed to account for significant common ownership when evaluating whether supposedly competing corporations are economically independent.<br><br>Market-concentration analysis shall consider situations in which the same major institutional shareholders possess substantial governance rights, voting authority, or influence across several nominal competitors.<br><br><strong>6. Separation of Custody From Control.</strong><br>Congress shall establish limits preventing an asset manager from simultaneously possessing extraordinary:<ul><li>Custody power.</li><li>Voting power.</li><li>Corporate-governance power.</li><li>Financial-data power.</li><li>Ownership interests across competing industries.</li><li>Control over critical financial infrastructure.</li></ul>Where concentration becomes systemically excessive, structural separation may be ordered.<br><br><strong>7. Protection of Beneficial Investors.</strong><br>Any structural remedy shall distinguish between the <strong>assets beneficially owned by investors</strong> and the <strong>management, voting, or governance authority exercised by the intermediary</strong>.<br><br>Retirement accounts, pensions, index-fund investors, and ordinary shareholders shall not lose their investments merely because the fund manager or institutional intermediary is subjected to antitrust remedies.<br><br>The goal of this policy is to decentralize governance power without confiscating or impairing the lawful property of underlying investors."""

text = insert_into_section(text, 'sec-banking', 'sec-energy', [
    policy('Common Ownership Competition Act', 'Separate passive custody of American savings from concentrated economy-wide governance power.', p4, ['economy','finance','reform']),
])

if text.count('98.7'):
    raise SystemExit('Old version reference remains after replacement')
for title in titles:
    if text.count(title) != 1:
        raise SystemExit(f'Expected exactly one occurrence after insertion: {title}')
    pos = text.index(title)
    if 'isNew:true' not in text[pos:pos+25000]:
        raise SystemExit(f'NEW tag missing near {title}')

path.write_text(text, encoding='utf-8')
print(f'Updated {old_version_count} version references and added five approved policies. Existing isNew tags preserved.')
